import os

hits = []
for root, dirs, files in os.walk('/'):
    # 跳过一些无关的系统目录以加快搜索
    dirs[:] = [d for d in dirs if d not in ('proc', 'sys', 'dev', 'run') and not d.startswith('.')]
    for f in files:
        if '销量' in f or '产品销量表' in f:
            hits.append(os.path.join(root, f))

print('全盘匹配结果:')
for h in hits:
    print(h)
if not hits:
    print('（未找到）')
